import UIKit
import WebKit
import XCTest
@testable import YabPhone

/// The current main's full SVGs are independently rendered by WebKit.
/// Native paper, marker and ink are drawn in an owned, real scene window.
@MainActor
final class SettingsReferenceTests: XCTestCase {
    private var window: UIWindow?
    private weak var previous: UIWindow?
    override func tearDown() {
        window?.isHidden = true; window?.rootViewController = nil; window = nil
        previous?.makeKey(); previous = nil
    }
    private func host() throws -> UIViewController {
        let scene = try XCTUnwrap(UIApplication.shared.connectedScenes.compactMap { $0 as? UIWindowScene }
            .first { $0.activationState == .foregroundActive })
        previous = scene.windows.first(where: \.isKeyWindow)
        let owned = UIWindow(windowScene: scene); window = owned
        owned.frame = CGRect(x: 0, y: 0, width: 320, height: 540)
        let controller = UIViewController(); owned.rootViewController = controller
        controller.view.backgroundColor = .white; owned.makeKeyAndVisible()
        return controller
    }
    private func web(in controller: UIViewController) -> WKWebView {
        let config = WKWebViewConfiguration(); config.websiteDataStore = .nonPersistent()
        let web = WKWebView(frame: CGRect(x: 0, y: 500, width: 24, height: 24), configuration: config)
        web.scrollView.contentInsetAdjustmentBehavior = .never
        controller.view.addSubview(web); return web
    }

    func testExactCurrentMainPenInkAndMarkersMatchIndependentWebKitSvg() async throws {
        let controller = try host(), web = self.web(in: controller)
        XCTAssertEqual(SettingsPenArt.names, macInk.keys.sorted())
        XCTAssertEqual(SettingsPenArt.markerNames, macMarkers.keys.sorted())
        for isMarker in [false, true] {
            let originals = isMarker ? macMarkers : macInk
            for (name, original) in originals.sorted(by: { $0.key < $1.key }) {
                let reference = try await render(original, name: name + (isMarker ? ".marker" : ".ink"), in: web)
                let native = try XCTUnwrap(SettingsPenArt.image(name, marker: isMarker))
                    .withTintColor(.black, renderingMode: .alwaysOriginal)
                let a = try bitmap(reference), b = try bitmap(native)
                let value = coverage(a, b)
                XCTAssertGreaterThan(value.union, 50 * 255, name)
                XCTAssertGreaterThan(value.iou, 0.9, "The exact current-main SVG, independently rendered: \(name)")
                attach(reference, "Current main SVG: " + name + (isMarker ? " marker" : " ink"))
                attach(native, "Actual native path: " + name + (isMarker ? " marker" : " ink"))
                if name == "general", !isMarker {
                    let format = UIGraphicsImageRendererFormat(); format.scale = 3; format.opaque = true
                    let moved = UIGraphicsImageRenderer(size: CGSize(width: 24, height: 24), format: format).image { output in
                        UIColor.white.setFill(); output.fill(CGRect(x: 0, y: 0, width: 24, height: 24))
                        native.draw(in: CGRect(x: 3, y: 0, width: 24, height: 24))
                    }
                    XCTAssertLessThan(coverage(a, try bitmap(moved)).iou, 0.9,
                                      "The same strict metric must reject a real shifted native drawing")
                }
            }
        }
    }

    func testCurrentMainPaperMarkerAndInkPaintAtRootAndHeroSizesAcrossTraits() async throws {
        let controller = try host(), web = self.web(in: controller)
        let pages = SettingsIndex.groups(alternateIcons: true).flatMap { $0 }
        XCTAssertEqual(pages, [.general, .search, .appearance, .appIcon, .tabs, .sync, .ai, .spaces, .history, .passwords, .autofill, .extensions, .privacy, .about, .feedback])
        var tiles: [(SettingsPageID, SettingsIconView, SettingsIconView)] = []
        for (i, page) in pages.enumerated() {
            let root = SettingsIconView(), hero = SettingsIconView()
            root.frame = CGRect(x: 10 + CGFloat(i % 3) * 104, y: 20 + CGFloat(i / 3) * 92, width: 28, height: 28)
            hero.frame = CGRect(x: root.frame.maxX + 8, y: root.frame.minY, width: 56, height: 56)
            let name = try XCTUnwrap(SettingsIndex.macMark(page))
            XCTAssertEqual(name, page.rawValue, "The actual page drawing must not alias Passwords to the generic Key artwork")
            root.configure(mark: name, tint: SettingsIndex.macTint(page), side: 28)
            hero.configure(mark: name, tint: SettingsIndex.macTint(page), side: 56)
            controller.view.addSubview(root); controller.view.addSubview(hero)
            tiles.append((page, root, hero))
        }
        var pictures: [UIImage] = []
        for style in [UIUserInterfaceStyle.light, .dark] {
            controller.overrideUserInterfaceStyle = style
            controller.view.backgroundColor = style == .dark ? .black : .white
            for (_, root, hero) in tiles {
                root.overrideUserInterfaceStyle = style; hero.overrideUserInterfaceStyle = style
                root.setNeedsDisplay(); hero.setNeedsDisplay()
            }
            controller.view.setNeedsLayout(); controller.view.layoutIfNeeded(); await Task.yield()
            let actual = try snapshot(); pictures.append(actual)
            attach(actual, style == .dark ? "Current main pen tiles and heroes in Dark" : "Current main pen tiles and heroes in Light")
            for (page, root, hero) in tiles {
                let reference = try await render(try composition(page, dark: style == .dark),
                                                 name: page.rawValue + (style == .dark ? ".dark" : ".light"), in: web,
                                                 dark: style == .dark)
                let expected = try bitmap(reference)
                for (view, size) in [(root, CGFloat(28)), (hero, CGFloat(56))] {
                    XCTAssertEqual(view.bounds.width, size, accuracy: 0.001)
                    XCTAssertEqual(view.bounds.height, size, accuracy: 0.001)
                    XCTAssertEqual(view.intrinsicContentSize, CGSize(width: size, height: size))
                    XCTAssertFalse(view.isAccessibilityElement); XCTAssertTrue(view.accessibilityElementsHidden)
                    XCTAssertFalse(view.isUserInteractionEnabled)
                    let window = try XCTUnwrap(window), pixels = try XCTUnwrap(actual.cgImage)
                    let rect = view.convert(view.bounds, to: window)
                    let crop = CGRect(x: rect.minX * 3, y: rect.minY * 3, width: rect.width * 3, height: rect.height * 3)
                    let picture = UIImage(cgImage: try XCTUnwrap(pixels.cropping(to: crop)), scale: 3, orientation: .up)
                    let received = try bitmap(picture)
                    var difference = 0
                    for i in 0..<72 * 72 {
                        for channel in 0..<3 { difference += abs(Int(expected[i * 4 + channel]) - Int(received[i * 4 + channel])) }
                    }
                    XCTAssertLessThan(Double(difference) / Double(72 * 72 * 3 * 255), 0.025,
                                      "Actual full-size paper/marker/ink must match the independent current-main composition: \(page.rawValue), \(size), \(style)")
                    attach(picture, "Actual pen tile: \(page.rawValue) \(Int(size)) \(style == .dark ? "Dark" : "Light")")
                }
            }
        }
        XCTAssertNotEqual(pictures[0].pngData(), pictures[1].pngData(), "The actual native paint must respond to trait changes")
        XCTAssertNotNil(SettingsPenArt.image("sync"), "Current main has its own Sync pen art; it no longer uses the old SF fallback")
    }

    private func render(_ svg: String, name: String, in web: WKWebView, dark: Bool = false) async throws -> UIImage {
        let ground = dark ? "black" : "white"
        web.loadHTMLString("<meta name='viewport' content='width=device-width,initial-scale=1'><title>\(name)</title><style>body{margin:0;background:\(ground)}svg{display:block;width:24px;height:24px}</style>\(svg)", baseURL: nil)
        let deadline = Date().addingTimeInterval(5)
        while Date() < deadline, web.title != name || web.isLoading { try await Task.sleep(for: .milliseconds(10)) }
        XCTAssertEqual(web.title, name); XCTAssertFalse(web.isLoading)
        let config = WKSnapshotConfiguration(); config.rect = web.bounds
        return try await withCheckedThrowingContinuation { continuation in
            web.takeSnapshot(with: config) { image, error in
                if let error { continuation.resume(throwing: error) }
                else if let image { continuation.resume(returning: image) }
                else { continuation.resume(throwing: NSError(domain: "OwnedPenSvg", code: 1)) }
            }
        }
    }
    private func composition(_ page: SettingsPageID, dark: Bool) throws -> String {
        let original = try XCTUnwrap(macInk[page.rawValue])
        func group(_ svg: String, fill: String) throws -> String {
            let beginning = try XCTUnwrap(svg.range(of: "<g "))
            let end = try XCTUnwrap(svg.range(of: "</g>", range: beginning.lowerBound..<svg.endIndex))
            return String(svg[beginning.lowerBound..<end.upperBound]).replacingOccurrences(of: "fill=\"#000\"", with: "fill=\"\(fill)\"")
        }
        let paper = dark ? "rgb(43.095,43.095,46.92)" : "rgb(250.92,249.9,248.115)"
        let ink = dark ? "rgb(240.975,240.975,243.015)" : "rgb(28.05,28.05,30.09)"
        var content = "<rect width='384' height='384' rx='96' fill='\(paper)'/><rect x='3.4285714285714284' y='3.4285714285714284' width='377.14285714285717' height='377.14285714285717' rx='92.57142857142857' fill='none' stroke='\(dark ? "white" : "black")' stroke-opacity='.1' stroke-width='6.857142857142857'/>"
        if let svg = macMarkers[page.rawValue] {
            let fill: String
            // The actual main's page colors (PenArt.mark).
            switch page {
            case .ai: fill = "#a96be0"
            case .about: fill = "#8b6cf0"
            case .spaces, .autofill: fill = "#34b85a"
            case .passwords: fill = "#808087"
            case .privacy: fill = "#3b82f0"
            case .history: fill = "#f0943a"
            case .extensions: fill = "#615fd8"
            default: throw NSError(domain: "OwnedPenComposition", code: 2)
            }
            let alpha = page == .about ? "1" : (dark ? ".75" : ".6")
            content += "<g opacity='\(alpha)'>\(try group(svg, fill: fill))</g>"
        }
        content += try group(original, fill: ink)
        return "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 384 384'>\(content)</svg>"
    }
    private func coverage(_ a: [UInt8], _ b: [UInt8]) -> (iou: Double, union: Int) {
        var intersection = 0, union = 0
        for i in 0..<72 * 72 {
            let left = 255 - Int(a[i * 4]), right = 255 - Int(b[i * 4])
            intersection += min(left, right); union += max(left, right)
        }
        return (Double(intersection) / Double(max(1, union)), union)
    }
    private func snapshot() throws -> UIImage {
        let window = try XCTUnwrap(window)
        let format = UIGraphicsImageRendererFormat(); format.scale = 3; format.opaque = true
        var drawn = false
        let image = UIGraphicsImageRenderer(bounds: window.bounds, format: format).image { _ in
            drawn = window.drawHierarchy(in: window.bounds, afterScreenUpdates: true)
        }
        XCTAssertTrue(drawn, "Only real scene-attached native content is visual evidence")
        return image
    }
    private func bitmap(_ image: UIImage) throws -> [UInt8] {
        let format = UIGraphicsImageRendererFormat(); format.scale = 3; format.opaque = true
        let normalized = UIGraphicsImageRenderer(size: CGSize(width: 24, height: 24), format: format).image { output in
            UIColor.white.setFill(); output.fill(CGRect(x: 0, y: 0, width: 24, height: 24))
            image.draw(in: CGRect(x: 0, y: 0, width: 24, height: 24))
        }
        let pixels = try XCTUnwrap(normalized.cgImage)
        var bytes = [UInt8](repeating: 255, count: 72 * 72 * 4)
        try bytes.withUnsafeMutableBytes { buffer in
            let context = try XCTUnwrap(CGContext(data: buffer.baseAddress, width: 72, height: 72, bitsPerComponent: 8,
                bytesPerRow: 72 * 4, space: CGColorSpaceCreateDeviceRGB(),
                bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue | CGBitmapInfo.byteOrder32Big.rawValue))
            context.draw(pixels, in: CGRect(x: 0, y: 0, width: 72, height: 72))
        }
        return bytes
    }
    private func attach(_ image: UIImage, _ name: String) {
        let item = XCTAttachment(image: image); item.name = name; item.lifetime = .keepAlways; add(item)
    }
